// Generated by `cargo xtask gen` from each tool's `--help`. Do not edit.

export const TOOL_HELP = {
	recab:
		"A/B slot + boot-selection manager\n\nUsage: recab [OPTIONS] <COMMAND>\n\nCommands:\n  status        Show detected A/B status\n  init          Set up the boot layout of a freshly installed system: systemd-boot, the boot entries (both A/B slots, or the one mutable root) and the installed kernel\n  stage         Write a prebuilt system into the inactive slot (formats the slot)\n  set-next      Schedule one trial boot of the inactive slot (A or B)\n  commit        Commit currently booted slot as known-good and default\n  rollback      Configure next boot to previously known-good slot\n  trial         After startup: commit a healthy trial boot, or reboot into the known-good slot (run by the trial service on every boot)\n  health        Wait for startup to finish and report how it ended: the verdict a trial judges by (read-only; needs no A/B layout)\n  install-unit  Write recab's package contents into a tree: the trial service (systemd unit or OpenRC service), enabled, and the list of machine state `stage` carries\n  help          Print this message or the help of the given subcommand(s)\n\nOptions:\n      --json     Machine-readable output: `status` and `health` print JSON, and any command that fails prints its error as one JSON object on stderr\n  -h, --help     Print help\n  -V, --version  Print version",
	recinit:
		"Rootless initramfs builder for Linux\n\nUsage: recinit [OPTIONS] <COMMAND>\n\nCommands:\n  build-tiny     Build a tiny initramfs for live ISO boot\n  build-install  Build the busybox initramfs that boots an installed system (either distro)\n  help           Print this message or the help of the given subcommand(s)\n\nOptions:\n  -q, --quiet    Quiet mode (suppress progress messages)\n  -h, --help     Print help\n  -V, --version  Print version",
	reciso:
		'Create bootable UEFI ISOs from kernel + initramfs + rootfs\n\nUsage: reciso [OPTIONS] --kernel <KERNEL> --initrd <INITRD> --rootfs <ROOTFS> --label <LABEL> --output <OUTPUT> --build-uki <BUILD_UKIS>\n\nOptions:\n  -k, --kernel <KERNEL>\n          Path to kernel image (vmlinuz)\n\n  -i, --initrd <INITRD>\n          Path to initramfs image\n\n  -r, --rootfs <ROOTFS>\n          Path to rootfs image (EROFS)\n\n  -l, --label <LABEL>\n          ISO volume label\n\n  -o, --output <OUTPUT>\n          Output ISO path\n\n      --build-uki <BUILD_UKIS>\n          A boot entry\'s UKI, built inline (at least one). Format: "name:extra_cmdline:filename" Example: "Emergency:emergency:myos-emergency.efi"\n\n      --extra-file <EXTRA_FILES>\n          Add an extra file to the ISO. Format: "src:dst" Example: "/tmp/initramfs-installed.img:boot/initramfs-installed.img"\n\n      --overlay-image <OVERLAY_IMAGE>\n          Live overlay payload image (EROFS) to include\n\n      --os-name <OS_NAME>\n          OS name for the boot menu (e.g., "LevitateOS")\n\n      --os-id <OS_ID>\n          OS identifier (e.g., "levitateos")\n\n      --os-version <OS_VERSION>\n          OS version (e.g., "1.0")\n\n      --no-checksum\n          Skip checksum generation\n\n      --live-payload-layout <LAYOUT>\n          Layout for live payloads (only `iso-files`, the default)\n\n          Possible values:\n          - iso-files: Payloads are files under `live/` in the ISO filesystem\n          \n          [default: iso-files]\n\n      --systemd-boot <SYSTEMD_BOOT>\n          systemd-boot UEFI binary (default: the build host\'s)\n          \n          [default: /usr/lib/systemd/boot/efi/systemd-bootx64.efi]\n\n  -q, --quiet\n          Quiet mode - only print errors\n\n  -h, --help\n          Print help (see a summary with \'-h\')\n\n  -V, --version\n          Print version\n\nEXAMPLES:\n    # Boot entries, one UKI each (format: name:extra_cmdline:filename)\n    reciso -k vmlinuz -i initramfs.img -r rootfs.erofs -l MYISO --build-uki \'Normal::myos.efi\' --build-uki \'Emergency:emergency:myos-emergency.efi\' --os-name MyOS --os-id myos --os-version 1.0 -o output.iso\n\n    # With live overlay image (EROFS)\n    reciso -k vmlinuz -i initramfs.img -r rootfs.erofs -l MYISO --build-uki \'Normal::myos.efi\' --overlay-image live-overlay.erofs -o output.iso\n\nREQUIREMENTS:\n    - systemd-boot (dnf install systemd-boot)\n    - xorriso (dnf install xorriso)\n    - mtools (dnf install mtools)\n    - ukify (dnf install systemd-ukify)',
	recpart:
		"Mode-aware partition planning and apply backend\n\nUsage: recpart [OPTIONS] <COMMAND>\n\nCommands:\n  list-disks  Enumerate candidate target disks\n  inspect     Show a disk's partition table, partitions (filesystem, used space, mounts) and free gaps\n  plan        Generate a deterministic partition plan\n  apply       Apply a partition plan directly to disk\n  help        Print this message or the help of the given subcommand(s)\n\nOptions:\n      --json     Emit machine-readable JSON (errors too, on stderr)\n  -h, --help     Print help\n  -V, --version  Print version",
	recchroot:
		"Enter chroot with proper bind mounts (like arch-chroot)\n\nUsage: recchroot <CHROOT_DIR> [COMMAND]...\n\nArguments:\n  <CHROOT_DIR>  Chroot directory (e.g., /mnt)\n  [COMMAND]...  Command to run (default: root's login shell in the target)\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version",
	recfstab:
		"Reads mounted filesystems under a root directory and outputs fstab entries naming each partition by PARTUUID (or filesystem UUID/LABEL, or PARTLABEL). PARTUUID is what the boot entries name the root by, and it survives the reformat an A/B update makes. Designed for system installation workflows where you need to generate /etc/fstab for a newly installed system.\n\nUsage: recfstab [OPTIONS] <ROOT>\n\nArguments:\n  <ROOT>\n          Root directory to scan for mounted filesystems (e.g., /mnt)\n\nOptions:\n  -L, --label\n          Use filesystem LABEL instead of PARTUUID for device identification\n\n  -U, --uuid\n          Use the filesystem UUID instead of PARTUUID\n\n  -p, --partuuid\n          Use partition UUID (PARTUUID), the default\n\n  -t, --partlabel\n          Use partition LABEL (PARTLABEL) instead of PARTUUID\n\n  -w, --write\n          Append the entries to <ROOT>/etc/fstab; refused (E036) when it already has entries for the same mount points\n\n      --replace\n          With --write: replace the fstab's entries for those mount points\n\n      --json\n          Print the entries, the fstab's current entries and warnings as JSON (errors go to stderr as JSON)\n\n  -h, --help\n          Print help (see a summary with '-h')\n\n  -V, --version\n          Print version",
	recsetup:
		"Set up an extracted system: time zone, locale, keymap, hostname, accounts, boot and services\n\nUsage: recsetup [OPTIONS] <COMMAND>\n\nCommands:\n  inspect  Describe the target and list what can be chosen (time zones, locales, keymaps, ...)\n  plan     Check a request and print the exact commands, without running them\n  apply    Run the plan's commands in order, stopping at the first failure\n  help     Print this message or the help of the given subcommand(s)\n\nOptions:\n      --json     Emit machine-readable JSON (errors too, on stderr)\n  -h, --help     Print help\n  -V, --version  Print version",
	recstrap:
		"Extracts the EROFS rootfs image to a target directory. This is the pacstrap equivalent - it only extracts files; the live install docs describe the rest of the installation.\n\nUsage: recstrap [OPTIONS] <TARGET>\n\nArguments:\n  <TARGET>\n          Target directory (must be mounted, e.g., /mnt)\n\nOptions:\n      --rootfs <ROOTFS>\n          Rootfs image (auto-detected on the live ISO if not specified)\n\n  -f, --force\n          Shorthand for --allow-non-mountpoint --allow-nonempty\n\n      --allow-non-mountpoint\n          Allow a target directory that is not a mount point\n\n      --allow-nonempty\n          Allow a target directory that already contains files\n\n      --allow-host-root-fs\n          Allow extracting onto a filesystem the running system has mounted at / or another system directory such as /home (never implied by --force)\n\n  -q, --quiet\n          Quiet mode - minimal output for scripting\n\n  -c, --check\n          Check mode - run pre-flight validation only, don't extract\n\n      --json\n          Print progress as JSON lines on stdout (one event per line: start, progress, verify, done; with --check, one checked); errors go to stderr as JSON\n\n  -h, --help\n          Print help (see a summary with '-h')\n\n  -V, --version\n          Print version",
} as const;
